import React, { useState } from "react";

function Login() {

  const [mobile, setMobile] = useState("");
  const [otp, setOtp] = useState("");
  const [generatedOTP, setGeneratedOTP] = useState("");
  const [showOTP, setShowOTP] = useState(false);
  const [message, setMessage] = useState("");

  // Send OTP
  const sendOTP = () => {

    if (mobile.length !== 10 || isNaN(mobile)) {
      setMessage("Please enter valid mobile number");
      return;
    }

    const newOTP =
      Math.floor(100000 + Math.random() * 900000).toString();

    setGeneratedOTP(newOTP);

    console.log("OTP:", newOTP);

    setShowOTP(true);

    setMessage("OTP Sent Successfully");
  };

  // Verify OTP
  const verifyOTP = () => {

    if (otp === generatedOTP) {

      localStorage.setItem("user", mobile);

      setMessage("Login Successful ✅");

      setTimeout(() => {
        window.location.href = "/";
      }, 1000);

    } else {

      setMessage("Invalid OTP ❌");
    }
  };

  return (

    <div style={styles.container}>

      <div style={styles.card}>

        <div style={styles.logo}>
          ⚖️
        </div>

        <h1 style={styles.title}>
          JusticeLens AI
        </h1>

        <p style={styles.subtitle}>
          Login with Mobile OTP
        </p>

        <div style={styles.inputBox}>

          <span style={styles.code}>
            +91
          </span>

          <input
            type="text"
            placeholder="Enter Mobile Number"
            value={mobile}
            maxLength={10}
            onChange={(e) => setMobile(e.target.value)}
            style={styles.input}
          />

        </div>

        {!showOTP && (

          <button
            style={styles.button}
            onClick={sendOTP}
          >
            Send OTP
          </button>

        )}

        {showOTP && (

          <>
            <input
              type="text"
              placeholder="Enter OTP"
              value={otp}
              maxLength={6}
              onChange={(e) => setOtp(e.target.value)}
              style={styles.otpInput}
            />

            <button
              style={styles.button}
              onClick={verifyOTP}
            >
              Verify OTP
            </button>
          </>

        )}

        {message && (
          <p style={styles.message}>
            {message}
          </p>
        )}

      </div>

    </div>
  );
}

const styles = {

  container: {
    height: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background:
      "linear-gradient(135deg,#0f172a,#1e3a8a,#312e81)"
  },

  card: {
    width: "380px",
    padding: "40px",
    borderRadius: "20px",
    background: "rgba(255,255,255,0.1)",
    backdropFilter: "blur(15px)",
    border: "1px solid rgba(255,255,255,0.2)",
    boxShadow: "0 10px 40px rgba(0,0,0,0.3)",
    textAlign: "center",
    color: "#fff"
  },

  logo: {
    fontSize: "60px",
    marginBottom: "10px"
  },

  title: {
    marginBottom: "5px"
  },

  subtitle: {
    color: "#cbd5e1",
    marginBottom: "25px"
  },

  inputBox: {
    display: "flex",
    alignItems: "center",
    background: "rgba(255,255,255,0.12)",
    borderRadius: "12px",
    marginBottom: "20px",
    padding: "0 12px"
  },

  code: {
    fontWeight: "bold"
  },

  input: {
    flex: 1,
    padding: "15px",
    background: "transparent",
    border: "none",
    outline: "none",
    color: "#fff",
    fontSize: "16px"
  },

  otpInput: {
    width: "100%",
    padding: "15px",
    borderRadius: "12px",
    border: "none",
    outline: "none",
    marginBottom: "20px",
    background: "rgba(255,255,255,0.12)",
    color: "#fff",
    fontSize: "16px"
  },

  button: {
    width: "100%",
    padding: "15px",
    borderRadius: "12px",
    border: "none",
    background:
      "linear-gradient(90deg,#2563eb,#7c3aed)",
    color: "#fff",
    fontSize: "16px",
    fontWeight: "bold",
    cursor: "pointer"
  },

  message: {
    marginTop: "15px",
    color: "#facc15",
    fontWeight: "bold"
  }
};

export default Login;
